 <div class="scene" aria-busy="false"><div class="content">${sceneContent(family)}</div><canvas aria-hidden="true"></canvas><div class="forced-placeholder" aria-hidden="true"><i></i><i></i><i></i></div><div class="error"><h3>The demo request failed.</h3><p>Play a new cycle to retry. This outcome is immediate.</p></div></div>
