  const status=host.classList.contains('is-error')?'The request failed. Recovery content is available immediately.':s.phase==='inspection'?'Design inspection is frozen. Use Finish inspection or R to exit.':s.phase==='ready'?'Content is available. Play a cycle to compare the complete motion.':s.phase==='refreshing'?'Refreshing; existing content remains visible and usable.':s.phase==='handoff'?`Ready; playing the complete ${Math.round(s.duration)}ms handoff.`:s.static?'Still pending; motion is static. Readiness is unchanged.':`Loading with ${engine?.animations.idle.id.split('/').at(-1)??'selected animation'}. ${s.pointer?'Pointer lift is active.':'Pointer response is off or suspended.'}`;
