  [...root.querySelectorAll('.phase-strip span')].forEach((span,i)=>{span.textContent=labels[i];span.classList.toggle('active',s.phase==='ready'?i===2:s.phase==='pending'?i===0:(s.phase==='handoff'||s.phase==='inspection')&&(i===1&&s.progress<.87||i===2&&s.progress>.29));});
