 function play(kind){clearTimers();if(engine.phase==='inspection')engine.finish('Exit frozen design inspection.');started=performance.now();engine.start(kind==='refresh');if(kind==='play'||kind==='refresh')later(()=>engine.ready(),1100);if(kind==='late')later(()=>engine.ready(),4100);if(kind==='supersede')later(()=>{engine.ready();later(()=>{engine.start();log('New application intent supersedes the previous handoff.');later(()=>engine.ready(),850);},150);},700);}
 root.querySelectorAll('[data-family]').forEach(button=>button.addEventListener('click',()=>{labConfig.family=button.dataset.family;labConfig.idle=idleChoices[labConfig.family][0];labConfig.handoff=current===1?'fade':'signature';mount(current);}));
